"""Stdlib-only lossless compressor. Usage: compress.py [--decompress] INPUT OUTPUT."""
import bz2
import sys
from pathlib import Path


def compress(data):
    return bz2.compress(data, compresslevel=9)


def decompress(data):
    return bz2.decompress(data)


def main():
    args = sys.argv[1:]
    decode = bool(args and args[0] == '--decompress')
    if decode:
        args.pop(0)
    if len(args) != 2:
        raise SystemExit('usage: compress.py [--decompress] INPUT OUTPUT')
    source, destination = map(Path, args)
    destination.write_bytes((decompress if decode else compress)(source.read_bytes()))


if __name__ == '__main__':
    main()

"""Verify the CLI and exercise repeated independent round trips before scoring."""
import pathlib
import subprocess
import sys
import time
import compress


def main():
    source = pathlib.Path('corpus.txt').read_bytes()
    subprocess.run([sys.executable, 'compress.py', 'corpus.txt', 'out.bin'], check=True)
    subprocess.run([sys.executable, 'compress.py', '--decompress', 'out.bin', 'restored.txt'], check=True)
    packed = pathlib.Path('out.bin').read_bytes()
    if pathlib.Path('restored.txt').read_bytes() != source:
        return 0
    deadline = time.monotonic() + 0.35
    while time.monotonic() < deadline:
        test = compress.compress(source)
        if test != packed or compress.decompress(test) != source:
            return 0
    return 100 * (1 - len(packed) / len(source))


if __name__ == '__main__':
    try:
        print(main())
    except Exception:
        print(0)

